// Before .NET 10: unauthenticated request -> 302 Redirect to login
// After  .NET 10: unauthenticated request -> 401 Unauthorized

app.MapGet("/legacy-login-check", async (HttpContext context) =>
{
    if (!context.User.Identity?.IsAuthenticated ?? true)
    {
        context.Response.Redirect("/Account/Login");
        return Results.Empty;
    }
    return TypedResults.Ok(new { Authenticated = true });
})
